n = 15
min_edges = 22

def has_cycle_of_length(edges, length):
    """Check if the graph has a cycle of given length"""
    adj = {i: set() for i in range(n)}
    for u, v in edges:
        adj[u].add(v)
        adj[v].add(u)

    # BFS/DFS to find cycles
    # For small lengths, we can enumerate
    if length == 3:
        for i in range(n):
            for j in adj[i]:
                if j > i:
                    for k in adj[j]:
                        if k > j and k in adj[i]:
                            return True
        return False
    elif length == 4:
        for i in range(n):
            for j in adj[i]:
                if j > i:
                    for k in adj[j]:
                        if k > j and k != i:
                            for l in adj[k]:
                                if l > k and l in adj[i]:
                                    return True
        return False
    else:
        # General cycle detection using DFS
        # For a cycle of length 'length', we need a path of length 'length-1' 
        # from some vertex back to itself
        for start in range(n):
            # DFS with path tracking
            stack = [(start, [start])]
            while stack:
                node, path = stack.pop()
                if len(path) == length:
                    if start in adj[node]:
                        return True
                    continue
                for neighbor in adj[node]:
                    if neighbor not in path:
                        stack.append((neighbor, path + [neighbor]))
        return False

