            return True
        for c in range(k):
            valid = True
            for neighbor in adj[v]:
                if neighbor < v and colors[neighbor] == c:
                    valid = False
                    break
            if valid:
                colors[v] = c
                if backtrack(v + 1):
                    return True
                colors[v] = -1
        return False

    return backtrack(0)

