import random
from collections import deque

n = 15
min_edges = 22

def get_distance(adj, u, v, n):
    """BFS distance between u and v"""
    if u == v:
        return 0
    dist = {u: 0}
    queue = deque([u])
    while queue:
        node = queue.popleft()
        for neighbor in adj[node]:
            if neighbor not in dist:
                dist[neighbor] = dist[node] + 1
                if neighbor == v:
                    return dist[neighbor]
                queue.append(neighbor)
    return float('inf')

def can_add_edge(adj, u, v, n):
    """Check if adding edge (u,v) would create a cycle of length < 7"""
    # Adding (u,v) creates a cycle of length dist(u,v) + 1
    d = get_distance(adj, u, v, n)
    return d >= 6  # dist >= 6 means cycle length >= 7

def try_greedy_construction(num_trials=100000):
    best = None

    for trial in range(num_trials):
        adj = {i: set() for i in range(n)}
        edges = []

